'use strict';
// A single browser-local rehearsal with explicit student/teacher viewpoints.
const practiceBar=document.createElement('section');practiceBar.className='practice-switcher';practiceBar.setAttribute('aria-label','혼자 연습 시점 전환');$('.workspace').prepend(practiceBar);
const integratedEntrance=screens.entrance;
screens.entrance=()=>integratedEntrance().replace('먼저 연습해보기','혼자 연습하기');
function beginPractice(viewpoint){closeModal();Object.assign(classroom,{practiceMode:true,practiceStudentStep:'orientation',created:true,name:'혼자 연습 수업',topic:lessonTopics[0],groups:1,size:6,minutes:15,code:'PRACT1',joined:6,phase:'대기',paused:true,remaining:900,group:1,notice:''});priorities=[null,null];try{localStorage.removeItem(preferenceKey);}catch{}Object.assign(state,{guideStep:'video',guideCompleted:false,ready:false,roleRevealed:false,secretHidden:false,opening:'',voted:false,vote:null,voteReason:''});persist();saveClassroom();if(viewpoint==='teacher')teacherGo('teacher-lobby');else navigate('orientation',true);toast('같은 연습 수업에서 학생·선생님 화면을 바꿔 볼 수 있어요.');}
function practiceTeacherRoute(){return classroom.phase==='대기'?'teacher-lobby':classroom.phase==='종료'?'teacher-report':'teacher-live';}
function practiceStudentRoute(){if(!preferencesReady()||!state.ready)return state.guideCompleted?'role':classroom.practiceStudentStep||'orientation';if(classroom.phase==='종료')return 'reflection';if(classroom.phase==='추리')return 'vote';if(classroom.phase==='토론')return state.roleRevealed?'discussion':'role';return classroom.practiceStudentStep||'lobby';}
const renderWithoutPractice=render;
render=function(){renderWithoutPractice();practiceBar.hidden=!classroom.practiceMode;if(!classroom.practiceMode)return;const teacher=isTeacher();if(!teacher&&current!=='entrance'){classroom.practiceStudentStep=current;saveClassroom();}practiceBar.innerHTML=`<div class="practice-context"><span class="practice-dot"></span><div><strong>혼자 연습 중</strong><small>나와 컴퓨터 참가자 5명 · 같은 수업에서 시점 전환</small></div></div><div class="practice-view-switch" role="group" aria-label="연습 화면 선택"><button data-practice-view="student" aria-pressed="${!teacher}">${icon('chat',15)}학생 시점</button><button data-practice-view="teacher" aria-pressed="${teacher}">${icon('users',15)}선생님 시점</button></div><button class="practice-exit" data-practice-exit>연습 나가기</button>`;};
window.addEventListener('click',e=>{const trigger=e.target.closest('[data-action="practice"]'),start=e.target.closest('[data-practice-start]'),switcher=e.target.closest('[data-practice-view]'),exit=e.target.closest('[data-practice-exit]');if(trigger){e.preventDefault();e.stopImmediatePropagation();openModal(`<p class="eyebrow">혼자 연습하기</p><h2 id="modal-title">어느 화면부터 살펴볼까요?</h2><p>컴퓨터 참가자 5명이 있는 연습 수업을 준비해 드려요. 진행 중에도 학생·선생님 시점을 바꿀 수 있어요.</p><div class="practice-start-options"><button class="button wide" data-practice-start="student">학생으로 연습하기 ${icon('arrow',16)}</button><button class="button secondary wide" data-practice-start="teacher">선생님으로 연습하기 ${icon('arrow',16)}</button></div><p class="fine">연습 진행은 이 브라우저에만 저장됩니다. 새 연습은 현재 수업 시연을 연습용 수업으로 바꿉니다.</p>`);return;}if(start){e.preventDefault();e.stopImmediatePropagation();beginPractice(start.dataset.practiceStart);return;}if(switcher){e.preventDefault();e.stopImmediatePropagation();closeModal();if(switcher.dataset.practiceView==='teacher')teacherGo(practiceTeacherRoute());else navigate(practiceStudentRoute(),true);return;}if(exit){e.preventDefault();e.stopImmediatePropagation();classroom.practiceMode=false;saveClassroom();navigate('entrance',true);toast('연습 기록은 유지했어요.');return;}if(e.target.closest('#reset-demo')){classroom.practiceMode=false;saveClassroom();}if(e.target.closest('[data-teacher="teacher-create"]')&&classroom.practiceMode){classroom.practiceMode=false;saveClassroom();}},true);
document.addEventListener('submit',e=>{if(e.target.id==='teacher-create-form'){classroom.practiceMode=false;saveClassroom();}},true);
render();
